package main

import (
	"sync"
	"time"
)

type entry struct {
	value     string
	expiresAt time.Time
}

type Store struct {
	mu      sync.RWMutex
	data    map[string]*entry
	stopCh  chan struct{}
	sweeper *time.Ticker
}

func NewStore() *Store {
	s := &Store{
		data:   make(map[string]*entry),
		stopCh: make(chan struct{}),
	}
	s.sweeper = time.NewTicker(1 * time.Second)
	go s.sweepLoop()
	return s
}

func (s *Store) sweepLoop() {
	for {
		select {
		case <-s.sweeper.C:
			s.sweep()
		case <-s.stopCh:
			s.sweeper.Stop()
			return
		}
	}
}

func (s *Store) sweep() {
	s.mu.Lock()
	defer s.mu.Unlock()
	now := time.Now()
	for k, e := range s.data {
		if now.After(e.expiresAt) {
			delete(s.data, k)
		}
	}
	cacheEntries.Set(float64(len(s.data)))
}

func (s *Store) Put(key, value string, ttl time.Duration) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.data[key] = &entry{
		value:     value,
		expiresAt: time.Now().Add(ttl),
	}
	cacheEntries.Set(float64(len(s.data)))
}

func (s *Store) Get(key string) (string, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	e, ok := s.data[key]
	if !ok {
		return "", false
	}
	if time.Now().After(e.expiresAt) {
		delete(s.data, key)
		cacheEntries.Set(float64(len(s.data)))
		return "", false
	}
	return e.value, true
}

func (s *Store) Delete(key string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	_, ok := s.data[key]
	if ok {
		delete(s.data, key)
		cacheEntries.Set(float64(len(s.data)))
	}
	return ok
}

func (s *Store) Close() {
	close(s.stopCh)
}
