package main

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"
)

func TestPutAndGet(t *testing.T) {
	srv := newServer()

	// PUT a value
	req := httptest.NewRequest(http.MethodPut, "/cache/k1", nil)
	req.Header.Set("Content-Type", "application/json")
	body := `{"value": "v", "ttl_seconds": 60}`
	req.Body = jsonBody(body)
	rr := httptest.NewRecorder()
	srv.ServeHTTP(rr, req)
	if rr.Code != http.StatusCreated && rr.Code != http.StatusOK {
		t.Errorf("PUT /cache/k1: expected 201 or 200, got %d", rr.Code)
	}

	// GET the value
	req = httptest.NewRequest(http.MethodGet, "/cache/k1", nil)
	rr = httptest.NewRecorder()
	srv.ServeHTTP(rr, req)
	if rr.Code != http.StatusOK {
		t.Errorf("GET /cache/k1: expected 200, got %d", rr.Code)
	}
	var resp getResponse
	if err := json.NewDecoder(rr.Body).Decode(&resp); err != nil {
		t.Fatalf("decode response: %v", err)
	}
	if resp.Key != "k1" || resp.Value != "v" {
		t.Errorf("unexpected response: %+v", resp)
	}
}

func TestGetMissingAndExpired(t *testing.T) {
	srv := newServer()

	// GET missing key
	req := httptest.NewRequest(http.MethodGet, "/cache/nope", nil)
	rr := httptest.NewRecorder()
	srv.ServeHTTP(rr, req)
	if rr.Code != http.StatusNotFound {
		t.Errorf("GET /cache/nope: expected 404, got %d", rr.Code)
	}

	// PUT with short TTL
	req = httptest.NewRequest(http.MethodPut, "/cache/expire", nil)
	req.Header.Set("Content-Type", "application/json")
	body := `{"value": "v", "ttl_seconds": 1}`
	req.Body = jsonBody(body)
	rr = httptest.NewRecorder()
	srv.ServeHTTP(rr, req)
	if rr.Code != http.StatusCreated && rr.Code != http.StatusOK {
		t.Errorf("PUT /cache/expire: expected 201 or 200, got %d", rr.Code)
	}

	// Wait for expiry
	time.Sleep(1100 * time.Millisecond)

	// GET expired key
	req = httptest.NewRequest(http.MethodGet, "/cache/expire", nil)
	rr = httptest.NewRecorder()
	srv.ServeHTTP(rr, req)
	if rr.Code != http.StatusNotFound {
		t.Errorf("GET /cache/expire after expiry: expected 404, got %d", rr.Code)
	}
}

func TestPutValidation(t *testing.T) {
	srv := newServer()

	tests := []struct {
		name       string
		body       string
		wantStatus int
	}{
		{"missing value", `{"ttl_seconds": 5}`, http.StatusBadRequest},
		{"zero ttl", `{"value": "v", "ttl_seconds": 0}`, http.StatusBadRequest},
		{"negative ttl", `{"value": "v", "ttl_seconds": -1}`, http.StatusBadRequest},
		{"malformed json", `{invalid}`, http.StatusBadRequest},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			req := httptest.NewRequest(http.MethodPut, "/cache/test", nil)
			req.Header.Set("Content-Type", "application/json")
			req.Body = jsonBody(tc.body)
			rr := httptest.NewRecorder()
			srv.ServeHTTP(rr, req)
			if rr.Code != tc.wantStatus {
				t.Errorf("expected %d, got %d", tc.wantStatus, rr.Code)
			}
		})
	}
}

func TestDelete(t *testing.T) {
	srv := newServer()

	// PUT a value
	req := httptest.NewRequest(http.MethodPut, "/cache/k1", nil)
	req.Header.Set("Content-Type", "application/json")
	body := `{"value": "v", "ttl_seconds": 60}`
	req.Body = jsonBody(body)
	rr := httptest.NewRecorder()
	srv.ServeHTTP(rr, req)
	if rr.Code != http.StatusCreated && rr.Code != http.StatusOK {
		t.Errorf("PUT: expected 201 or 200, got %d", rr.Code)
	}

	// DELETE the value
	req = httptest.NewRequest(http.MethodDelete, "/cache/k1", nil)
	rr = httptest.NewRecorder()
	srv.ServeHTTP(rr, req)
	if rr.Code != http.StatusOK && rr.Code != http.StatusNoContent {
		t.Errorf("DELETE: expected 200 or 204, got %d", rr.Code)
	}

	// GET should now 404
	req = httptest.NewRequest(http.MethodGet, "/cache/k1", nil)
	rr = httptest.NewRecorder()
	srv.ServeHTTP(rr, req)
	if rr.Code != http.StatusNotFound {
		t.Errorf("GET after DELETE: expected 404, got %d", rr.Code)
	}

	// DELETE missing key
	req = httptest.NewRequest(http.MethodDelete, "/cache/missing", nil)
	rr = httptest.NewRecorder()
	srv.ServeHTTP(rr, req)
	if rr.Code != http.StatusNotFound {
		t.Errorf("DELETE missing: expected 404, got %d", rr.Code)
	}
}

func TestHealthAndMetrics(t *testing.T) {
	srv := newServer()

	// Health endpoint
	req := httptest.NewRequest(http.MethodGet, "/health", nil)
	rr := httptest.NewRecorder()
	srv.ServeHTTP(rr, req)
	if rr.Code != http.StatusOK {
		t.Errorf("/health: expected 200, got %d", rr.Code)
	}

	// Metrics endpoint
	req = httptest.NewRequest(http.MethodGet, "/metrics", nil)
	rr = httptest.NewRecorder()
	srv.ServeHTTP(rr, req)
	if rr.Code != http.StatusOK {
		t.Errorf("/metrics: expected 200, got %d", rr.Code)
	}
}

func jsonBody(s string) *jsonBodyReader {
	return &jsonBodyReader{data: []byte(s)}
}

type jsonBodyReader struct {
	data []byte
	pos  int
}

func (r *jsonBodyReader) Read(p []byte) (n int, err error) {
	if r.pos >= len(r.data) {
		return 0, io.EOF
	}
	n = copy(p, r.data[r.pos:])
	r.pos += n
	return n, nil
}

func (r *jsonBodyReader) Close() error {
	return nil
}
